    seen = set()
    seen_add = seen.add
    if key is not None:
        for item in seq:
            if item not in seen:
                seen_add(item)
                yield item
    else:
        for item in seq:
            val = key(item)
            if val not in seen:
                seen_add(val)
                yield item

